using UnityEngine;
using UnityEngine.InputSystem;
namespace FarmPrototype.Player { public sealed class FarmEquipmentController:MonoBehaviour { [SerializeField] GameObject hoe; [SerializeField] GameObject seeds; [SerializeField] GameObject wateringCan; void Start(){Select(hoe);var a=GetComponent<Animator>();var hand=a!=null?a.GetBoneTransform(HumanBodyBones.RightHand):null;if(hand==null){Debug.LogError("RightHand not found on Animator.",this);return;} Attach(hoe,hand,new Vector3(.05f,0,0),new Vector3(10,90,80));Attach(seeds,hand,Vector3.zero,new Vector3(0,90,0));Attach(wateringCan,hand,new Vector3(.03f,0,0),new Vector3(0,90,70));}void Update(){var k=Keyboard.current;if(k==null)return;if(k.digit1Key.wasPressedThisFrame)Select(hoe);if(k.digit2Key.wasPressedThisFrame)Select(seeds);if(k.digit3Key.wasPressedThisFrame)Select(wateringCan);if(k.digit4Key.wasPressedThisFrame)Select(null);}void Select(GameObject x){if(hoe)hoe.SetActive(x==hoe);if(seeds)seeds.SetActive(x==seeds);if(wateringCan)wateringCan.SetActive(x==wateringCan);}static void Attach(GameObject x,Transform h,Vector3 p,Vector3 r){if(!x)return;x.transform.SetParent(h,false);x.transform.localPosition=p;x.transform.localRotation=Quaternion.Euler(r);}}}
